for (def field : params.required) { if (!ctx.containsKey(field) || ctx[field] == null) { throw new IllegalArgumentException('Required normalized evidence field missing'); } }
if (!ctx.evidence_id.startsWith('EV-') || ctx.evidence_id.length() != 67 || ctx.tenant_id.length() == 0 || ctx.tenant_id.length() > 100) { throw new IllegalArgumentException('Invalid normalized identity'); }
if (!params.modes.contains(ctx.source_mode)) { throw new IllegalArgumentException('Unknown source provenance'); }
Instant eventTime = Instant.parse(ctx['@timestamp']);
Instant received = Instant.parse(ctx.ingested_at);
ctx.ingested_at = received.toString();
long lag = received.toEpochMilli() - eventTime.toEpochMilli();
ctx.ingestion_lag_ms = Math.max(0L, lag);
if (ctx.quality_flags == null) { ctx.quality_flags = []; }
if (lag < -300000 && !ctx.quality_flags.contains('FUTURE_CLOCK_SKEW')) { ctx.quality_flags.add('FUTURE_CLOCK_SKEW'); }
if (lag > 900000 && !ctx.quality_flags.contains('LATE_ARRIVAL')) { ctx.quality_flags.add('LATE_ARRIVAL'); }
